generated_qss:
QMainWindow, QWidget { background-color: #FDF6E3; color: #586E75; font-size: 10pt; }

QGroupBox {
    border: 1px solid #D3CBB7;
    border-radius: 3px;
    margin-top: 8px;
    padding-top: 0px;
    font-weight: bold;
    color: #268BD2;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 8px;
    padding: 0 4px;
}

QTabWidget::pane
{
    border: 1px solid #D3CBB7;
    top: -1px;
}

QTabBar::tab
{
    background-color: #EEE8D5;
    color: #586E75;
    padding: 6px 12px;
    border: 1px solid #D3CBB7;
    border-top-left-radius: 3px;
    border-top-right-radius: 3px;
    min-width: 70px;
}

QTabBar::tab:selected
{
    background-color: #E4DDC8;
    color: #268BD2;
    font-weight: 600;
    margin-bottom: 0px;
}

QTabBar::tab:hover
{
    background-color: #268BD2;
    color: #FDF6E3;
}

QTabBar::tab:!selected
{
    margin-top: 2px;
}

QListWidget { background-color: #EEE8D5; }
QListWidget::item:selected { background-color: #268BD2; color: #FDF6E3; }

QTableView {
    background-color: #EEE8D5;
    alternate-background-color: #FDF6E3;
    color: #586E75;
    gridline-color: #D3CBB7;
    selection-background-color: #E4DDC8;
}
QHeaderView::section {
    background-color: #E4DDC8;
    color: #268BD2;
    border: 1px solid #D3CBB7;
    padding: 3px;
    font-weight: bold;
}
QTableWidget {
    background-color: #EEE8D5;
    color: #586E75;
    gridline-color: #D3CBB7;
}

/* ---- Global input sizing ---------------------------------------------- */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QAbstractSpinBox {
    background-color: #E4DDC8;
    color: #586E75;
    border: 1px solid #D3CBB7;
    border-radius: 2px;
    min-height: 28px;
    padding-top: 4px;
    padding-bottom: 4px;
    padding-left: 4px;
    padding-right: 4px;
}
QComboBox QAbstractItemView {
    background: #E4DDC8;
    color: #586E75;
    selection-background-color: #268BD2;
    selection-color: #FDF6E3;
}
QComboBox QAbstractItemView::item { min-height: 28px; }
QComboBox::drop-down { border: none; min-height: 28px; }

QTextEdit {
    background-color: #EEE8D5;
    color: #586E75;
    border: 1px solid #D3CBB7;
}

QPushButton {
    background-color: #E4DDC8;
    color: #586E75;
    border: 1px solid #D3CBB7;
    border-radius: 3px;
    padding: 5px 10px;
}
QPushButton:hover { background-color: #268BD2; color: #FDF6E3; }
QPushButton:disabled { color: #93A1A1; border-color: #D3CBB7; }

/* ---- Named action buttons (set via objectName) ------------------------ */
QPushButton#btnConnect    { background-color: #859900;     color: #FDF6E3; font-weight: bold; }
QPushButton#btnDisconnect { background-color: #DC322F;  color: #FDF6E3; }
QPushButton#btnRead       { background-color: #859900;        color: #FDF6E3; font-weight: bold; }
QPushButton#btnWrite      { background-color: #268BD2;       color: #FDF6E3; font-weight: bold; }
QPushButton#btnWriteRead  { background-color: #6C71C4;  color: #FDF6E3; font-weight: bold; }
QPushButton#btnScan       { background-color: #CB4B16;        color: #FDF6E3; font-weight: bold; }
QPushButton#btnApply      { font-weight: bold; }
QPushButton#btnSpyStart   { background-color: #859900;     color: #FDF6E3; font-weight: bold; font-size: 13px; padding: 6px; }
QPushButton#btnSpyStop    { background-color: #DC322F;  color: #FDF6E3; font-weight: bold; font-size: 13px; padding: 6px; }

QLabel#specgenSectionHeading {
    font-size: 13pt;
    font-weight: 600;
    color: #586E75;
    margin-top: 8px;
    margin-bottom: 4px;
}

QLabel#noteLabel { color: #B58900; font-size: 10px; }
QLabel#mutedLabel { color: #93A1A1; }
/* [XREF: file-picker] validated file-status line colors */
QLabel#statusOk { color: #859900; }
QLabel#statusError { color: #DC322F; }

QPushButton[saveDirty="true"] {
    background-color: #859900;
    color: #FDF6E3;
    font-weight: 600;
    border-radius: 2px;
    padding: 4px 12px;
}
QPushButton[saveDirty="true"]:hover { background-color: #96AB00; }

QStatusBar { background-color: #E4DDC8; color: #586E75; }
QSplitter::handle { background: #D3CBB7; }
QScrollBar:vertical { background: #FDF6E3; width: 10px; }
QScrollBar::handle:vertical { background: #D3CBB7; border-radius: 4px; min-height: 20px; }
QCheckBox { color: #586E75; spacing: 5px; }
QRadioButton { color: #586E75; spacing: 6px; }
QProgressDialog { background-color: #FDF6E3; color: #586E75; }
